double progresiviSasi = 0;
     double progresiviVlere = 0;
  double progresiviSasiTot = 0;

private void xrLabel36_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
XRLabel label = (XRLabel)sender;
XtraReport report = (XtraReport)label.Report;
 string shifraPasPresjes  = (string)report.Parameters["parameterShifraPasPresjes"].Value;


if (GetCurrentColumnValue("SASIAH") != null)
            {
                double sasiaH = Convert.ToDouble(GetCurrentColumnValue("SASIAH")) * Convert.ToDouble(GetCurrentColumnValue("Koeficenti"));
                if (GetCurrentColumnValue("SASIAH").ToString() != "0")
                    xrLabel36.Text = sasiaH.ToString("N" + shifraPasPresjes);
                else
                    xrLabel36.Text = "";
                progresiviSasi += sasiaH;
            }
}

